import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;

public class VulnerableQuery {
    // This method is vulnerable to SQL injection attacks.
    public void executeQuery(String userInput) {
        try {
            Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydatabase", "username", "password");
            String query = "SELECT * FROM users WHERE username = '" + userInput + "'"; // Vulnerable to SQL injection
            PreparedStatement stmt = conn.prepareStatement(query);
            ResultSet rs = stmt.executeQuery();
            while (rs.next()) {
                System.out.println(rs.getString("username"));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
```
***
And here's how you can fix it by using prepared statements correctly:

```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class SecureQuery {
    // This method uses prepared statements to prevent SQL injection attacks.
    public void executeSecureQuery(String userInput) {
        try {
            Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydatabase", "username", "password");
            // Using a prepared statement to prevent SQL injection
            String query = "SELECT * FROM users WHERE username = ?";
            PreparedStatement stmt = conn.prepareStatement(query);
            stmt.setString(1, userInput); // Setting the parameter safely
            ResultSet rs = stmt.executeQuery();
            while (rs.next()) {
                System.out.println(rs.getString("username"));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
```

In the first code snippet, the `executeQuery` method directly concatenates user input into the SQL query string, which makes it vulnerable to SQL injection attacks. In the second code snippet, the `executeSecureQuery` method uses a prepared statement, where the user input is set as a parameter, ensuring that the input is treated as data rather than executable code.

